#!/bin/bash
# erzeugt von tools/seiten_luecken.py - Kandidaten fuer ungesehene Waende nachregistrieren
set -e
mkdir -p /media/oem/scan/rc-park_daten/schwab_auto/seiten_nachholen/roh
rm -rf /media/oem/scan/rc-park_daten/schwab_auto/seiten_nachholen/bilder /media/oem/scan/rc-park_daten/schwab_auto/seiten_nachholen/vorbereitet.json /media/oem/scan/rc-park_daten/schwab_auto/seiten_nachholen/merkmale.json /media/oem/scan/rc-park_daten/schwab_auto/seiten_nachholen/db.db /media/oem/scan/rc-park_daten/schwab_auto/seiten_nachholen/lg   # Zwischenstaende eines frueheren Laufs (Downloads und roh/ bleiben)
/media/oem/scan/venv-seg/bin/python -I /home/oem/git/rc-park/tools/commons_harvest.py --lat 47.992925 --lon 7.854041 --radius 250 --max 60 --search "Schwabentor Freiburg im Breisgau" --out /media/oem/scan/rc-park_daten/schwab_auto/seiten_nachholen/commons   # freie Lizenzen, manifest.json
python3 /home/oem/git/rc-park/tools/online_ansichten_holen.py --aus /media/oem/scan/rc-park_daten/schwab_auto/seiten_nachholen/hochblick --suche "Schwabentor Freiburg" "Freiburg Luftbild" "Freiburg Panorama" --max 40 || true   # Hochblicke (Commons): sehen Seiten ueber Nachbardaechern
python3 /home/oem/git/rc-park/tools/openverse_holen.py --aus /media/oem/scan/rc-park_daten/schwab_auto/seiten_nachholen/openverse --suche "Schwabentor Freiburg" "Schwabentor" "Freiburg Altstadt Blick" --max 150 || true   # Flickr u. a. ueber Openverse, nur CC0/BY/BY-SA
for f in /media/oem/scan/rc-park_daten/schwab_auto/seiten_nachholen/commons/*.jpg /media/oem/scan/rc-park_daten/schwab_auto/seiten_nachholen/hochblick/orig/*.jpg /media/oem/scan/rc-park_daten/schwab_auto/seiten_nachholen/openverse/*.jpg; do [ -e "$f" ] && ln -sf "$f" /media/oem/scan/rc-park_daten/schwab_auto/seiten_nachholen/roh/dl_$(basename $(dirname "$f"))__$(basename "$f"); done
